CREATE TABLE public.user_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, interests text[] NOT NULL DEFAULT '{}', location text NOT NULL DEFAULT '' CHECK(length(location)<=100), categories text[] NOT NULL DEFAULT '{}', formats text[] NOT NULL DEFAULT '{}', date_from text NOT NULL DEFAULT '' CHECK(date_from='' OR date_from ~ '^\d{4}-\d{2}-\d{2}$'), date_until text NOT NULL DEFAULT '' CHECK(date_until='' OR date_until ~ '^\d{4}-\d{2}-\d{2}$'), internship_roles text[] NOT NULL DEFAULT '{}', work_formats text[] NOT NULL DEFAULT '{}', CHECK(cardinality(interests)<=30 AND cardinality(categories)<=5 AND cardinality(formats)<=3 AND cardinality(internship_roles)<=20 AND cardinality(work_formats)<=3));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_preferences TO authenticated; GRANT ALL ON public.user_preferences TO service_role; ALTER TABLE public.user_preferences ENABLE ROW LEVEL SECURITY; CREATE POLICY own_preferences ON public.user_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.user_marks(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN('saved','follow','checklist')), item_id text NOT NULL CHECK(length(item_id) BETWEEN 1 AND 200 AND item_id ~ '^[a-zA-Z0-9:_-]+$'), PRIMARY KEY(user_id,kind,item_id)); GRANT SELECT,INSERT,DELETE ON public.user_marks TO authenticated; GRANT ALL ON public.user_marks TO service_role; ALTER TABLE public.user_marks ENABLE ROW LEVEL SECURITY; CREATE POLICY own_marks ON public.user_marks FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.validate_user_preferences() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v text; BEGIN FOREACH v IN ARRAY NEW.interests || NEW.internship_roles LOOP IF length(trim(v)) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid preference'; END IF; END LOOP; IF NOT NEW.categories <@ ARRAY['Hackathons','Workshops','Meetups','Conferences','Competitions'] OR NOT NEW.formats <@ ARRAY['Online','Offline','Hybrid'] OR NOT NEW.work_formats <@ ARRAY['In-person','Remote','Hybrid'] THEN RAISE EXCEPTION 'Invalid format or category'; END IF; IF NEW.date_from<>'' THEN PERFORM NEW.date_from::date; END IF; IF NEW.date_until<>'' THEN PERFORM NEW.date_until::date; END IF; IF NEW.date_from<>'' AND NEW.date_until<>'' AND NEW.date_until<NEW.date_from THEN RAISE EXCEPTION 'Invalid date range'; END IF; RETURN NEW; END; $$; CREATE TRIGGER validate_preferences BEFORE INSERT OR UPDATE ON public.user_preferences FOR EACH ROW EXECUTE FUNCTION public.validate_user_preferences();